const anonymousCategories = ["Liderança", "Cronograma", "Ferramentas / acessos", "Ambiente", "Comunicação", "Carga de trabalho", "Sugestão", "Problema operacional", "Outro"];
const urgencyOptions = ["Baixa", "Média", "Alta", "Crítica"];
const feedbackStatusOptions = ["Todos", "Novo", "Em análise", "Resolvido", "Arquivado"];
const formalFeedbackTypeOptions = ["Todos", "Positivo", "Corretivo"];
const formalFeedbackStatusOptions = ["Todos", "Pendente de ciência", "Visualizado", "Ciente", "Arquivado"];
const fallbackFormalFeedbackCategories = ["Produtividade", "Qualidade", "ABS / Presença", "Atrasos", "Conduta", "Comportamento", "Reconhecimento positivo", "Alinhamento operacional", "Comunicação", "Outro"];
const climateQuestionTypeOptions = [
  ["ESCALA_1_5", "Escala 1 a 5"],
  ["SIM_NAO", "Sim/Não"],
  ["MULTIPLA_ESCOLHA", "Múltipla escolha"],
  ["TEXTO_LIVRE", "Texto livre"],
  ["NPS_0_10", "NPS 0 a 10"]
] as const;

function ptDate(value: string) {
  return new Intl.DateTimeFormat("pt-BR", { dateStyle: "short", timeZone: "America/Sao_Paulo" }).format(new Date(value));
}

function dateInputPlusDays(days: number) {
  const base = parseDateInput(currentOperationalDateInput()) ?? new Date();
  base.setUTCDate(base.getUTCDate() + days);
  return dateInputFromUtc(base);
}

export function ClimatePage() {
  const { data: session } = useSession();
  const role = String(session?.user?.role ?? "COLABORADOR").toUpperCase();
  const isAdmin = role === "ADMIN";
  const [payload, setPayload] = useState<ClimateSurveyListResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState("");
  const [selectedSurveyId, setSelectedSurveyId] = useState<string>("");
  const [answers, setAnswers] = useState<Record<string, string | number>>({});
  const [submittingSurveyId, setSubmittingSurveyId] = useState("");
  const [creatingSurvey, setCreatingSurvey] = useState(false);
  const [editingSurveyId, setEditingSurveyId] = useState("");
  const [newSurvey, setNewSurvey] = useState({
    title: "",
    description: "",
    startsAt: currentOperationalDateInput(),
    endsAt: dateInputPlusDays(14),
    anonymous: true,
    status: "ABERTA",
    targetType: "TODOS",
    targetValue: ""
  });

  const surveys = payload?.data ?? [];
  const selectedSurvey = selectedSurveyId ? surveys.find((survey) => survey.id === selectedSurveyId) ?? surveys[0] : surveys[0];

  useEffect(() => {
    void loadClimateSurveys();
  }, []);

  async function loadClimateSurveys() {
    setLoading(true);
    try {
      const result = await apiJson<ClimateSurveyListResponse>("/api/climate/surveys");
      setPayload(result);
      setSelectedSurveyId((current) => current || result.data[0]?.id || "");
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Não foi possível carregar Pesquisa de Clima.");
    } finally {
      setLoading(false);
    }
  }

  async function saveSurvey() {
    setCreatingSurvey(true);
    setMessage("");
    try {
      await apiJson<{ data: ClimateSurveyClient }>("/api/climate/surveys", {
        method: editingSurveyId ? "PATCH" : "POST",
        body: JSON.stringify(editingSurveyId ? { id: editingSurveyId, ...newSurvey } : newSurvey)
      });
      setMessage(editingSurveyId ? "Pesquisa atualizada com sucesso." : "Pesquisa criada com sucesso.");
      setNewSurvey({ ...newSurvey, title: "", description: "" });
      setEditingSurveyId("");
      await loadClimateSurveys();
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Não foi possível salvar a pesquisa.");
    } finally {
      setCreatingSurvey(false);
    }
  }

  function editSurvey(survey: ClimateSurveyClient) {
    setEditingSurveyId(survey.id);
    setNewSurvey({
      title: survey.title,
      description: survey.description,
      startsAt: survey.startsAt.slice(0, 10),
      endsAt: survey.endsAt.slice(0, 10),
      anonymous: survey.anonymous,
      status: survey.status,
      targetType: survey.targetType ?? "TODOS",
      targetValue: survey.targetValue ?? ""
    });
    setSelectedSurveyId(survey.id);
  }

  async function updateSurveyStatus(id: string, status: string) {
    setMessage("");
    try {
      await apiJson<{ data: ClimateSurveyClient }>("/api/climate/surveys", {
        method: "PATCH",
        body: JSON.stringify({ id, status })
      });
      setMessage(status === "ENCERRADA" ? "Pesquisa encerrada." : "Status da pesquisa atualizado.");
      await loadClimateSurveys();
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Não foi possível atualizar a pesquisa.");
    }
  }

  async function submitClimateSurvey(survey: ClimateSurveyClient) {
    setSubmittingSurveyId(survey.id);
    setMessage("");
    try {
      await apiJson<{ data: { message: string } }>("/api/climate/answers", {
        method: "POST",
        body: JSON.stringify({
          surveyId: survey.id,
          answers: survey.questions.map((question) => ({ questionId: question.id, value: answers[question.id] ?? "" }))
        })
      });
      setMessage("Pesquisa respondida com sucesso.");
      setAnswers({});
      await loadClimateSurveys();
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Não foi possível salvar sua resposta.");
    } finally {
      setSubmittingSurveyId("");
    }
  }

  function renderQuestionInput(question: ClimateQuestionClient) {
    const value = answers[question.id] ?? (question.type === "ESCALA_1_5" ? 3 : "");
    if (question.type === "ESCALA_1_5" || question.type === "NPS_0_10") {
      const max = question.type === "NPS_0_10" ? 10 : 5;
      return (
        <div className="mt-3 flex items-center gap-4">
          <input
            type="range"
            min="1"
            max={max}
            value={Number(value) || 1}
            onChange={(event) => setAnswers((current) => ({ ...current, [question.id]: Number(event.target.value) }))}
            className="w-full"
          />
          <span className="w-10 rounded-lg bg-blue-50 px-2 py-1 text-center text-sm font-black text-blue-700">{value}</span>
        </div>
      );
    }
    if (question.type === "SIM_NAO") {
      return (
        <select value={String(value)} onChange={(event) => setAnswers((current) => ({ ...current, [question.id]: event.target.value }))} className="mt-3 h-11 w-full rounded-lg border border-border px-3">
          <option value="">Selecione</option>
          <option>Sim</option>
          <option>Não</option>
        </select>
      );
    }
    if (question.type === "MULTIPLA_ESCOLHA") {
      return (
        <select value={String(value)} onChange={(event) => setAnswers((current) => ({ ...current, [question.id]: event.target.value }))} className="mt-3 h-11 w-full rounded-lg border border-border px-3">
          <option value="">Selecione</option>
          {question.options.map((option) => <option key={option}>{option}</option>)}
        </select>
      );
    }
    return (
      <textarea
        value={String(value)}
        onChange={(event) => setAnswers((current) => ({ ...current, [question.id]: event.target.value }))}
        className="mt-3 min-h-24 w-full rounded-lg border border-border p-3 outline-none"
        placeholder="Escreva sua resposta"
      />
    );
  }

  if (isAdmin) {
    const adminPayload = payload?.mode === "admin" ? payload : null;
    return (
      <div>
        <PageHeader title="Pesquisa de Clima" description="Pesquisas reais para resposta dos colaboradores e consolidação administrativa." icon={HeartPulse} actions={<TopActions />} />
        {message ? <div className="mb-4 rounded-lg border border-blue-100 bg-blue-50 px-4 py-3 text-sm font-bold text-blue-700">{message}</div> : null}
        <div className="mb-5 grid gap-4 md:grid-cols-2 xl:grid-cols-4">
          <StatCard title="Pesquisas abertas" value={adminPayload?.summary.open ?? 0} helper="ciclos ativos" icon={HeartPulse} tone="blue" />
          <StatCard title="Total de respostas" value={adminPayload?.summary.totalResponses ?? 0} helper="respostas salvas" icon={UsersRound} tone="green" />
          <StatCard title="Média de satisfação" value={adminPayload?.summary.satisfactionAverage ?? "-"} helper="escala 1 a 5" icon={Star} tone="gold" />
          <StatCard title="NPS" value={adminPayload?.summary.nps ?? "-"} helper="quando houver pergunta NPS" icon={Target} tone="orange" />
        </div>
        <div className="grid gap-5 xl:grid-cols-[420px_minmax(0,1fr)]">
          <Panel title={editingSurveyId ? "Editar pesquisa em rascunho" : "Criar pesquisa"}>
            <div className="space-y-3">
              <input value={newSurvey.title} onChange={(event) => setNewSurvey({ ...newSurvey, title: event.target.value })} className="h-11 w-full rounded-lg border border-border px-3" placeholder="Título" />
              <textarea value={newSurvey.description} onChange={(event) => setNewSurvey({ ...newSurvey, description: event.target.value })} className="min-h-24 w-full rounded-lg border border-border p-3 outline-none" placeholder="Descrição" />
              <div className="grid gap-3 md:grid-cols-2">
                <label className="block text-sm font-bold text-muted">Início<input type="date" value={newSurvey.startsAt} onChange={(event) => setNewSurvey({ ...newSurvey, startsAt: event.target.value })} className="mt-1 h-10 w-full rounded-lg border border-border px-3" /></label>
                <label className="block text-sm font-bold text-muted">Fim<input type="date" value={newSurvey.endsAt} onChange={(event) => setNewSurvey({ ...newSurvey, endsAt: event.target.value })} className="mt-1 h-10 w-full rounded-lg border border-border px-3" /></label>
              </div>
              <div className="grid gap-3 md:grid-cols-2">
                <select value={newSurvey.status} onChange={(event) => setNewSurvey({ ...newSurvey, status: event.target.value })} className="h-10 rounded-lg border border-border px-3">
                  <option value="RASCUNHO">Rascunho</option>
                  <option value="ABERTA">Aberta</option>
                  <option value="ENCERRADA">Encerrada</option>
                </select>
                <select value={newSurvey.targetType} onChange={(event) => setNewSurvey({ ...newSurvey, targetType: event.target.value })} className="h-10 rounded-lg border border-border px-3">
                  <option value="TODOS">Todos</option>
                  <option value="AGENTES">Agentes</option>
                  <option value="LOB">LOB específica</option>
                  <option value="CARGO_FUNCAO">Cargo/Função</option>
                  <option value="SUPERVISOR">Supervisor</option>
                </select>
              </div>
              <input value={newSurvey.targetValue} onChange={(event) => setNewSurvey({ ...newSurvey, targetValue: event.target.value })} className="h-10 w-full rounded-lg border border-border px-3" placeholder="Valor do público alvo, se aplicável" />
              <label className="flex items-center gap-2 text-sm font-bold text-navy-950">
                <input type="checkbox" checked={newSurvey.anonymous} onChange={(event) => setNewSurvey({ ...newSurvey, anonymous: event.target.checked })} />
                Pesquisa anônima
              </label>
              <div className="rounded-lg bg-slate-50 p-3 text-xs font-semibold leading-5 text-muted">
                Sem perguntas customizadas, o sistema cria o template padrão de clima com escala 1 a 5 e campos abertos.
              </div>
              <div className="flex flex-wrap gap-2">
              <button type="button" disabled={creatingSurvey || !newSurvey.title.trim()} onClick={saveSurvey} className="premium-button h-11 px-4 text-sm font-extrabold disabled:opacity-60">
                {creatingSurvey ? "Salvando..." : editingSurveyId ? "Salvar alterações" : "Criar pesquisa"}
              </button>
              {editingSurveyId ? (
                <button type="button" onClick={() => { setEditingSurveyId(""); setNewSurvey({ ...newSurvey, title: "", description: "", status: "ABERTA" }); }} className="h-11 rounded-lg border border-border px-4 text-sm font-bold">
                  Cancelar edição
                </button>
              ) : null}
              </div>
            </div>
          </Panel>
          <div className="space-y-5">
            <Panel title="Pesquisas">
              {loading ? (
                <EmptyState title="Carregando pesquisas" description="Buscando dados reais no banco." />
              ) : surveys.length ? (
                <SimpleTable
                  columns={["Pesquisa", "Período", "Status", "Respostas", "Ações"]}
                  rows={surveys.map((survey) => [
                    <button key={`${survey.id}-title`} type="button" onClick={() => setSelectedSurveyId(survey.id)} className="text-left font-extrabold text-blue-700">{survey.title}</button>,
                    `${ptDate(survey.startsAt)} até ${ptDate(survey.endsAt)}`,
                    <StatusBadge key={`${survey.id}-status`} status={survey.status} />,
                    survey.results?.responseCount ?? 0,
                    <div key={`${survey.id}-actions`} className="flex flex-wrap gap-2">
                      <button type="button" onClick={() => updateSurveyStatus(survey.id, "ABERTA")} className="rounded-lg border border-border px-2 py-1 text-xs font-bold">Abrir</button>
                      <button type="button" onClick={() => updateSurveyStatus(survey.id, "ENCERRADA")} className="rounded-lg border border-border px-2 py-1 text-xs font-bold">Encerrar</button>
                      {survey.status === "RASCUNHO" ? <button type="button" onClick={() => editSurvey(survey)} className="rounded-lg border border-border px-2 py-1 text-xs font-bold">Editar</button> : null}
                    </div>
                  ])}
                />
              ) : (
                <EmptyState title="Nenhuma pesquisa criada ainda." description="Crie uma pesquisa para começar a coletar respostas." />
              )}
            </Panel>
            <Panel title="Resultados da pesquisa selecionada" action="Exportar" actionOnClick={() => void downloadFile("/api/climate/surveys/export", "pesquisa_clima.xlsx").catch((error) => setMessage(error.message))}>
              {selectedSurvey?.results ? (
                <div className="space-y-4">
                  <div className="grid gap-3 md:grid-cols-3">
                    <MetricPill value={selectedSurvey.results.responseCount} label="Respostas" />
                    <MetricPill value={selectedSurvey.results.satisfactionAverage ?? "-"} label="Média" />
                    <MetricPill value={selectedSurvey.results.nps ?? "-"} label="NPS" />
                  </div>
                  <div className="space-y-3">
                    {selectedSurvey.results.questions.map((question) => (
                      <div key={question.id} className="rounded-lg border border-border p-3">
                        <div className="flex flex-wrap items-center justify-between gap-2">
                          <p className="font-extrabold text-navy-950">{question.question}</p>
                          <StatusBadge status={question.average === null ? `${question.answers} resposta(s)` : `Média ${question.average}`} />
                        </div>
                        {Object.keys(question.distribution).length ? (
                          <p className="mt-2 text-xs font-semibold text-muted">{Object.entries(question.distribution).map(([label, count]) => `${label}: ${count}`).join(" | ")}</p>
                        ) : null}
                        {question.comments.length ? (
                          <div className="mt-3 space-y-2">
                            {question.comments.slice(0, 4).map((comment, index) => (
                              <p key={`${question.id}-${index}`} className="rounded-lg bg-slate-50 px-3 py-2 text-sm text-navy-900">{comment}</p>
                            ))}
                          </div>
                        ) : null}
                      </div>
                    ))}
                  </div>
                </div>
              ) : (
                <EmptyState title="Nenhuma resposta registrada." description="Os resultados aparecem aqui após a primeira resposta." />
              )}
            </Panel>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div>
      <PageHeader title="Pesquisa de Clima" description="Responda pesquisas abertas e acompanhe pendências." icon={HeartPulse} actions={<TopActions />} />
      {message ? <div className="mb-4 rounded-lg border border-blue-100 bg-blue-50 px-4 py-3 text-sm font-bold text-blue-700">{message}</div> : null}
      <Panel title="Pesquisas abertas">
        {loading ? (
          <EmptyState title="Carregando pesquisas" description="Buscando pesquisas abertas." />
        ) : surveys.length ? (
          <div className="space-y-4">
            {surveys.map((survey) => (
              <div key={survey.id} className="rounded-lg border border-border p-4">
                <div className="flex flex-wrap items-start justify-between gap-3">
                  <div>
                    <h2 className="font-black text-navy-950">{survey.title}</h2>
                    <p className="mt-1 text-sm text-muted">{survey.description}</p>
                    <p className="mt-2 text-xs font-bold text-muted">Prazo: {ptDate(survey.endsAt)} · {survey.anonymous ? "Anônima" : "Identificada"}</p>
                  </div>
                  <StatusBadge status={survey.answered ? "Respondida" : "Pendente"} />
                </div>
                {survey.answered ? (
                  <EmptyState title="Pesquisa respondida com sucesso." description="Obrigado por contribuir." />
                ) : (
                  <div className="mt-4 space-y-3">
                    {survey.questions.map((question) => (
                      <label key={question.id} className="block rounded-lg border border-border p-3">
                        <span className="text-sm font-bold text-navy-950">{question.order}. {question.text}</span>
                        {renderQuestionInput(question)}
                      </label>
                    ))}
                    <button type="button" disabled={submittingSurveyId === survey.id} onClick={() => submitClimateSurvey(survey)} className="premium-button h-11 px-4 text-sm font-extrabold disabled:opacity-60">
                      {submittingSurveyId === survey.id ? "Enviando..." : "Enviar resposta"}
                    </button>
                  </div>
                )}
              </div>
            ))}
          </div>
        ) : (
          <EmptyState title="Nenhuma pesquisa aberta no momento." description="Quando houver uma pesquisa disponível, ela aparecerá aqui." />
        )}
      </Panel>
    </div>
  );
}

export function FormalFeedbackPage() {
  const defaultRange = getDefaultDateRange();
  const initialDetailOpenedRef = useRef(false);
  const [payload, setPayload] = useState<FormalFeedbackListResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [selectedFeedback, setSelectedFeedback] = useState<FormalFeedbackClient | null>(null);
  const [acknowledgeOpen, setAcknowledgeOpen] = useState(false);
  const [acknowledgeResponse, setAcknowledgeResponse] = useState("");
  const [saving, setSaving] = useState(false);
  const [filters, setFilters] = useState({
    employeeId: "",
    startDate: defaultRange.startDate,
    endDate: defaultRange.endDate,
    status: "Todos",
    type: "Todos",
    category: "Todos",
    lob: "",
    supervisor: "",
    jobTitle: "",
    skill: "",
    search: ""
  });
  const [draft, setDraft] = useState({
    employeeId: "",
    type: "Positivo",
    category: "Produtividade",
    title: "",
    description: ""
  });

  const loadFeedbacks = useCallback(async () => {
    setLoading(true);
    const params = buildFormalFeedbackParams(filters);
    try {
      const nextPayload = await apiJson<FormalFeedbackListResponse>(`/api/feedbacks?${params.toString()}`);
      setPayload(nextPayload);
      setMessage("");
      if (!draft.employeeId && nextPayload.options.employees[0]) {
        setDraft((current) => ({ ...current, employeeId: current.employeeId || nextPayload.options.employees[0].id }));
      }
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Não foi possível carregar Feedback Formal.");
    } finally {
      setLoading(false);
    }
  }, [draft.employeeId, filters]);

  useEffect(() => {
    void loadFeedbacks();
  }, [loadFeedbacks]);

  useEffect(() => {
    const employeeIdFromUrl = typeof window !== "undefined" ? new URLSearchParams(window.location.search).get("employeeId") : null;
    if (employeeIdFromUrl) setFilters((current) => ({ ...current, employeeId: employeeIdFromUrl }));
  }, []);

  useEffect(() => {
    if (initialDetailOpenedRef.current) return;
    const idFromUrl = typeof window !== "undefined" ? new URLSearchParams(window.location.search).get("id") : null;
    if (!idFromUrl) return;
    initialDetailOpenedRef.current = true;
    setMessage("");
    apiJson<{ data: FormalFeedbackClient }>(`/api/feedbacks/${encodeURIComponent(idFromUrl)}`)
      .then((detail) => setSelectedFeedback(detail.data))
      .catch((error) => setMessage(error instanceof Error ? error.message : "Não foi possível abrir o feedback."));
  }, []);

  const categories = payload?.options.categories.length ? payload.options.categories : fallbackFormalFeedbackCategories;
  const summary = payload?.summary;
  const canCreate = Boolean(payload?.permissions.canCreate);
  const canExport = Boolean(payload?.permissions.canExport);
  const viewerEmployeeId = payload?.viewer.employeeId ?? "";
  const exportParams = buildFormalFeedbackParams(filters);

  async function openFeedbackDetail(id: string) {
    setMessage("");
    try {
      const detail = await apiJson<{ data: FormalFeedbackClient }>(`/api/feedbacks/${encodeURIComponent(id)}`);
      setSelectedFeedback(detail.data);
      void loadFeedbacks();
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Não foi possível abrir o feedback.");
    }
  }

  async function createFeedback() {
    setSaving(true);
    setMessage("");
    try {
      const response = await apiJson<{ data: FormalFeedbackClient; message: string }>("/api/feedbacks", {
        method: "POST",
        body: JSON.stringify(draft)
      });
      setMessage(response.message);
      setDraft((current) => ({ ...current, title: "", description: "" }));
      await loadFeedbacks();
      setSelectedFeedback(response.data);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Não foi possível criar Feedback Formal.");
    } finally {
      setSaving(false);
    }
  }

  async function confirmAcknowledge() {
    if (!selectedFeedback) return;
    setSaving(true);
    setMessage("");
    try {
      const response = await apiJson<{ data: FormalFeedbackClient; message: string }>(`/api/feedbacks/${encodeURIComponent(selectedFeedback.id)}/acknowledge`, {
        method: "POST",
        body: JSON.stringify({ response: acknowledgeResponse })
      });
      setSelectedFeedback(response.data);
      setAcknowledgeOpen(false);
      setAcknowledgeResponse("");
      setMessage(response.message);
      await loadFeedbacks();
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Não foi possível confirmar ciência.");
    } finally {
      setSaving(false);
    }
  }

  async function archiveFeedback(feedback: FormalFeedbackClient) {
    setSaving(true);
    setMessage("");
    try {
      const response = await apiJson<{ data: FormalFeedbackClient; message: string }>(`/api/feedbacks/${encodeURIComponent(feedback.id)}/archive`, {
        method: "PATCH"
      });
      setSelectedFeedback(response.data);
      setMessage(response.message);
      await loadFeedbacks();
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Não foi possível arquivar feedback.");
    } finally {
      setSaving(false);
    }
  }

  return (
    <div>
      <PageHeader
        title="Feedback Formal"
        description="Feedbacks formais enviados pela liderança, com ciência do colaborador e histórico rastreável."
        icon={MessagesSquare}
        actions={<TopActions />}
      />

      {message ? <div className="mb-4 rounded-lg border border-blue-100 bg-blue-50 px-4 py-3 text-sm font-bold text-blue-700">{message}</div> : null}

      <div className="mb-5 grid gap-4 md:grid-cols-2 xl:grid-cols-6">
        <StatCard title="Total" value={summary?.total ?? 0} helper="feedbacks no filtro" icon={MessagesSquare} tone="blue" />
        <StatCard title="Pendentes" value={summary?.pending ?? 0} helper="aguardando ciência" icon={Clock} tone="orange" />
        <StatCard title="Visualizados" value={summary?.viewed ?? 0} helper="lidos pelo agente" icon={UserCheck} tone="purple" />
        <StatCard title="Cientes" value={summary?.acknowledged ?? 0} helper="ciência registrada" icon={CheckCircle2} tone="green" />
        <StatCard title="Positivos" value={summary?.positive ?? 0} helper="reconhecimentos" icon={Award} tone="green" />
        <StatCard title="Corretivos" value={summary?.corrective ?? 0} helper="alinhamentos" icon={AlertTriangle} tone="red" />
      </div>

      {canCreate ? (
        <Panel title="Novo feedback formal">
          <div className="grid gap-3 xl:grid-cols-[1.1fr_180px_220px_1fr]">
            <label className="block">
              <span className="mb-1.5 block text-sm font-bold text-muted">Colaborador</span>
              <select value={draft.employeeId} onChange={(event) => setDraft({ ...draft, employeeId: event.target.value })} className="h-11 w-full rounded-lg border border-border px-3 text-sm font-bold">
                {payload?.options.employees.length ? payload.options.employees.map((employee) => (
                  <option key={employee.id} value={employee.id}>
                    {employee.name} · {employee.wbLogin} · {employee.lob}
                  </option>
                )) : <option value="">Nenhum agente disponível</option>}
              </select>
            </label>
            <label className="block">
              <span className="mb-1.5 block text-sm font-bold text-muted">Tipo</span>
              <select value={draft.type} onChange={(event) => setDraft({ ...draft, type: event.target.value })} className="h-11 w-full rounded-lg border border-border px-3 text-sm font-bold">
                {formalFeedbackTypeOptions.filter((option) => option !== "Todos").map((option) => <option key={option}>{option}</option>)}
              </select>
            </label>
            <label className="block">
              <span className="mb-1.5 block text-sm font-bold text-muted">Categoria</span>
              <select value={draft.category} onChange={(event) => setDraft({ ...draft, category: event.target.value })} className="h-11 w-full rounded-lg border border-border px-3 text-sm font-bold">
                {categories.map((category) => <option key={category}>{category}</option>)}
              </select>
            </label>
            <label className="block">
              <span className="mb-1.5 block text-sm font-bold text-muted">Título</span>
              <input value={draft.title} onChange={(event) => setDraft({ ...draft, title: event.target.value })} className="h-11 w-full rounded-lg border border-border px-3 text-sm font-bold" placeholder="Resumo do feedback" />
            </label>
          </div>
          <div className="mt-3 grid gap-3 xl:grid-cols-[minmax(0,1fr)_180px] xl:items-end">
            <label className="block">
              <span className="mb-1.5 block text-sm font-bold text-muted">Descrição</span>
              <textarea value={draft.description} onChange={(event) => setDraft({ ...draft, description: event.target.value })} className="min-h-28 w-full rounded-lg border border-border p-3 text-sm font-semibold outline-none" placeholder="Descreva o contexto de forma objetiva e respeitosa." />
            </label>
            <button type="button" onClick={createFeedback} disabled={saving || !draft.employeeId || !draft.title.trim() || !draft.description.trim()} className="premium-button h-11 px-4 text-sm font-extrabold disabled:opacity-60">
              {saving ? "Enviando..." : "Enviar feedback"}
            </button>
          </div>
        </Panel>
      ) : null}

      <Panel title="Feedbacks formais" action={canExport ? "Exportar XLSX" : undefined} actionOnClick={canExport ? () => void downloadFile(`/api/feedbacks/export?${exportParams.toString()}`, "feedback_formal.xlsx").catch((error) => setMessage(error.message)) : undefined}>
        <div className="mb-4 grid gap-3 md:grid-cols-4 xl:grid-cols-9">
          <input type="date" value={filters.startDate} onChange={(event) => setFilters({ ...filters, startDate: event.target.value })} className="h-10 rounded-lg border border-border px-3" />
          <input type="date" value={filters.endDate} onChange={(event) => setFilters({ ...filters, endDate: event.target.value })} className="h-10 rounded-lg border border-border px-3" />
          <select value={filters.status} onChange={(event) => setFilters({ ...filters, status: event.target.value })} className="h-10 rounded-lg border border-border px-3">
            {formalFeedbackStatusOptions.map((option) => <option key={option}>{option}</option>)}
          </select>
          <select value={filters.type} onChange={(event) => setFilters({ ...filters, type: event.target.value })} className="h-10 rounded-lg border border-border px-3">
            {formalFeedbackTypeOptions.map((option) => <option key={option}>{option}</option>)}
          </select>
          <select value={filters.category} onChange={(event) => setFilters({ ...filters, category: event.target.value })} className="h-10 rounded-lg border border-border px-3">
            <option>Todos</option>
            {categories.map((category) => <option key={category}>{category}</option>)}
          </select>
          <input value={filters.lob} onChange={(event) => setFilters({ ...filters, lob: event.target.value })} className="h-10 rounded-lg border border-border px-3" placeholder="LOB" />
          <input value={filters.supervisor} onChange={(event) => setFilters({ ...filters, supervisor: event.target.value })} className="h-10 rounded-lg border border-border px-3" placeholder="Supervisor" />
          <input value={filters.skill} onChange={(event) => setFilters({ ...filters, skill: event.target.value })} className="h-10 rounded-lg border border-border px-3" placeholder="Skill" />
          <div className="flex gap-2">
            <input value={filters.search} onChange={(event) => setFilters({ ...filters, search: event.target.value })} className="h-10 min-w-0 flex-1 rounded-lg border border-border px-3" placeholder="Buscar" />
            <button type="button" onClick={loadFeedbacks} className="h-10 rounded-lg border border-border px-3 text-sm font-bold">Filtrar</button>
          </div>
        </div>

        {loading ? (
          <EmptyState title="Carregando feedbacks" description="Buscando feedbacks formais conforme sua permissão." />
        ) : payload?.data.length ? (
          <SimpleTable
            columns={["Data", "Colaborador", "LOB", "Autor", "Tipo", "Categoria", "Título", "Status", "Ciente em", "Ações"]}
            rows={payload.data.map((feedback) => [
              feedback.sentAt,
              <div key={`${feedback.id}-employee`} className="min-w-[160px]">
                <p className="font-extrabold text-navy-950">{feedback.employeeName}</p>
                <p className="text-xs font-semibold text-muted">{feedback.wbLogin}</p>
              </div>,
              feedback.lob,
              feedback.authorName,
              <FormalFeedbackTypeBadge key={`${feedback.id}-type`} type={feedback.typeLabel} />,
              feedback.category,
              <span key={`${feedback.id}-title`} className="line-clamp-2 max-w-[260px] text-sm font-bold">{feedback.title}</span>,
              <StatusBadge key={`${feedback.id}-status`} status={feedback.statusLabel} />,
              feedback.acknowledgedAt || "-",
              <div key={`${feedback.id}-actions`} className="flex flex-wrap gap-2">
                <button type="button" onClick={() => openFeedbackDetail(feedback.id)} className="rounded-lg border border-border px-2 py-1 text-xs font-bold">Ver</button>
                {feedback.employeeId === viewerEmployeeId && !["CIENTE", "ARQUIVADO"].includes(feedback.status) ? (
                  <button type="button" onClick={() => { setSelectedFeedback(feedback); setAcknowledgeOpen(true); }} className="rounded-lg bg-blue-600 px-2 py-1 text-xs font-bold text-white">Ciência</button>
                ) : null}
              </div>
            ])}
          />
        ) : (
          <EmptyState title="Nenhum feedback formal encontrado." description="Feedbacks enviados pela liderança aparecerão aqui conforme sua permissão." />
        )}
      </Panel>

      {selectedFeedback ? (
        <div className="fixed inset-0 z-50 grid place-items-center bg-navy-950/40 p-4 backdrop-blur-sm">
          <div className="card max-h-[88vh] w-full max-w-3xl overflow-y-auto p-5">
            <div className="mb-4 flex items-start justify-between gap-3">
              <div>
                <div className="flex flex-wrap items-center gap-2">
                  <FormalFeedbackTypeBadge type={selectedFeedback.typeLabel} />
                  <StatusBadge status={selectedFeedback.statusLabel} />
                </div>
                <h2 className="mt-3 text-xl font-black text-navy-950">{selectedFeedback.title}</h2>
                <p className="mt-1 text-sm font-semibold text-muted">{selectedFeedback.sentAt} · {selectedFeedback.category}</p>
              </div>
              <button type="button" onClick={() => setSelectedFeedback(null)} className="grid h-9 w-9 place-items-center rounded-lg hover:bg-slate-100">×</button>
            </div>
            <div className="grid gap-3 md:grid-cols-2">
              <InfoBox label="Colaborador" value={`${selectedFeedback.employeeName} · ${selectedFeedback.wbLogin}`} />
              <InfoBox label="Supervisor" value={selectedFeedback.supervisor} />
              <InfoBox label="Autor" value={`${selectedFeedback.authorName} · ${selectedFeedback.authorRole}`} />
              <InfoBox label="Ciência" value={selectedFeedback.acknowledgedAt || "Pendente"} />
            </div>
            <div className="mt-4 rounded-xl border border-border bg-slate-50 p-4">
              <p className="text-xs font-black uppercase tracking-wide text-muted">Descrição do feedback</p>
              <p className="mt-2 whitespace-pre-wrap text-sm font-semibold leading-6 text-navy-950">{selectedFeedback.description}</p>
            </div>
            {selectedFeedback.employeeResponse ? (
              <div className="mt-4 rounded-xl border border-blue-100 bg-blue-50 p-4">
                <p className="text-xs font-black uppercase tracking-wide text-blue-700">Resposta/observação do agente</p>
                <p className="mt-2 whitespace-pre-wrap text-sm font-semibold leading-6 text-blue-900">{selectedFeedback.employeeResponse}</p>
              </div>
            ) : null}
            <div className="mt-5 flex flex-wrap justify-end gap-2">
              {selectedFeedback.employeeId === viewerEmployeeId && !["CIENTE", "ARQUIVADO"].includes(selectedFeedback.status) ? (
                <button type="button" onClick={() => setAcknowledgeOpen(true)} className="premium-button h-10 px-4 text-sm font-extrabold">Confirmar ciência</button>
              ) : null}
              {canExport && selectedFeedback.status !== "ARQUIVADO" ? (
                <button type="button" onClick={() => archiveFeedback(selectedFeedback)} disabled={saving} className="h-10 rounded-lg border border-border px-4 text-sm font-extrabold text-navy-950 disabled:opacity-60">Arquivar</button>
              ) : null}
            </div>
          </div>
        </div>
      ) : null}

      {acknowledgeOpen && selectedFeedback ? (
        <div className="fixed inset-0 z-[60] grid place-items-center bg-navy-950/45 p-4 backdrop-blur-sm">
          <div className="card w-full max-w-xl overflow-hidden">
            <div className="border-b border-border bg-gradient-to-b from-white to-blue-50/70 px-5 py-4">
              <h2 className="text-lg font-black text-navy-950">Confirmar ciência</h2>
              <p className="mt-1 text-sm font-semibold text-muted">Confirme que você leu este feedback. Você pode adicionar uma observação, se desejar.</p>
            </div>
            <div className="p-5">
              <label className="block">
                <span className="mb-1.5 block text-sm font-bold text-muted">Observação/resposta do agente (opcional)</span>
                <textarea value={acknowledgeResponse} onChange={(event) => setAcknowledgeResponse(event.target.value)} className="min-h-32 w-full rounded-lg border border-border p-3 text-sm font-semibold outline-none" placeholder="Escreva uma observação, se quiser registrar contexto." />
              </label>
              <div className="mt-5 flex justify-end gap-2">
                <button type="button" onClick={() => setAcknowledgeOpen(false)} className="h-10 rounded-lg border border-border px-4 text-sm font-extrabold text-navy-950">Voltar</button>
                <button type="button" onClick={confirmAcknowledge} disabled={saving} className="premium-button h-10 px-4 text-sm font-extrabold disabled:opacity-60">
                  {saving ? "Confirmando..." : "Confirmar ciência"}
                </button>
              </div>
            </div>
          </div>
        </div>
      ) : null}
    </div>
  );
}

function buildFormalFeedbackParams(filters: {
  employeeId?: string;
  startDate: string;
  endDate: string;
  status: string;
  type: string;
  category: string;
  lob: string;
  supervisor: string;
  jobTitle: string;
  skill: string;
  search: string;
}) {
  const params = new URLSearchParams();
  if (filters.employeeId) params.set("employeeId", filters.employeeId);
  if (filters.startDate) params.set("startDate", filters.startDate);
  if (filters.endDate) params.set("endDate", filters.endDate);
  if (filters.status !== "Todos") params.set("status", filters.status);
  if (filters.type !== "Todos") params.set("type", filters.type);
  if (filters.category !== "Todos") params.set("category", filters.category);
  if (filters.lob.trim()) params.set("lob", filters.lob.trim());
  if (filters.supervisor.trim()) params.set("supervisor", filters.supervisor.trim());
  if (filters.jobTitle.trim()) params.set("jobTitle", filters.jobTitle.trim());
  if (filters.skill.trim()) params.set("skill", filters.skill.trim());
  if (filters.search.trim()) params.set("search", filters.search.trim());
  return params;
}

function FormalFeedbackTypeBadge({ type }: { type: string }) {
  const positive = type.toLowerCase().includes("positivo");
  return (
    <span className={cn("inline-flex rounded-md px-2 py-1 text-[11px] font-extrabold", positive ? "bg-emerald-50 text-emerald-700" : "bg-orange-50 text-orange-700")}>
      {type}
    </span>
  );
}

function InfoBox({ label, value }: { label: string; value: ReactNode }) {
  return (
    <div className="rounded-xl border border-border bg-white p-3">
      <p className="text-xs font-black uppercase tracking-wide text-muted">{label}</p>
      <div className="mt-1 break-words text-sm font-extrabold text-navy-950">{value || "-"}</div>
    </div>
  );
}

export function AnonymousFeedbackPage() {
  const [submitted, setSubmitted] = useState(false);
  const [message, setMessage] = useState("");
  const [anonymousForm, setAnonymousForm] = useState({ category: "Liderança", urgency: "Média", comment: "", allowContact: false });
  const [feedbackPayload, setFeedbackPayload] = useState<AnonymousFeedbackListResponse | null>(null);
  const [feedbackLoading, setFeedbackLoading] = useState(false);
  const [feedbackView, setFeedbackView] = useState<"loading" | "admin" | "submit" | "error">("loading");
  const [selectedFeedback, setSelectedFeedback] = useState<AnonymousFeedbackClient | null>(null);
  const [responseDraft, setResponseDraft] = useState("");
  const [responseSaving, setResponseSaving] = useState(false);
  const [deletingFeedbackId, setDeletingFeedbackId] = useState<string | null>(null);
  const [feedbackFilters, setFeedbackFilters] = useState({ status: "Todos", urgency: "Todos", category: "Todos", startDate: "", endDate: "", lob: "", jobTitle: "", search: "" });

  const loadAnonymousFeedback = useCallback(async () => {
    setFeedbackLoading(true);
    const params = new URLSearchParams();
    if (feedbackFilters.status !== "Todos") params.set("status", feedbackFilters.status);
    if (feedbackFilters.urgency !== "Todos") params.set("urgency", feedbackFilters.urgency);
    if (feedbackFilters.category !== "Todos") params.set("category", feedbackFilters.category);
    if (feedbackFilters.startDate) params.set("startDate", feedbackFilters.startDate);
    if (feedbackFilters.endDate) params.set("endDate", feedbackFilters.endDate);
    if (feedbackFilters.lob.trim()) params.set("lob", feedbackFilters.lob.trim());
    if (feedbackFilters.jobTitle.trim()) params.set("jobTitle", feedbackFilters.jobTitle.trim());
    if (feedbackFilters.search.trim()) params.set("search", feedbackFilters.search.trim());
    try {
      const payload = await apiJson<AnonymousFeedbackListResponse>(`/api/anonymous-feedback?${params.toString()}`);
      setFeedbackPayload(payload);
      setFeedbackView("admin");
    } catch (error) {
      if (error instanceof ApiRequestError && error.status === 403) {
        setFeedbackView("submit");
      } else {
        setFeedbackView("error");
        setMessage(error instanceof Error ? error.message : "Não foi possível carregar feedbacks.");
      }
    } finally {
      setFeedbackLoading(false);
    }
  }, [feedbackFilters.category, feedbackFilters.endDate, feedbackFilters.jobTitle, feedbackFilters.lob, feedbackFilters.search, feedbackFilters.startDate, feedbackFilters.status, feedbackFilters.urgency]);

  useEffect(() => {
    void loadAnonymousFeedback();
  }, [loadAnonymousFeedback]);

  async function submitAnonymousFeedback() {
    setMessage("");
    try {
      const payload = await apiJson<{ data: { message: string } }>("/api/anonymous-feedback", {
        method: "POST",
        body: JSON.stringify(anonymousForm)
      });
      setSubmitted(true);
      setMessage(payload.data.message);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Não foi possível enviar o feedback.");
    }
  }

  async function updateFeedbackStatus(id: string, status: string) {
    setMessage("");
    try {
      const payload = await apiJson<{ data: AnonymousFeedbackClient }>("/api/anonymous-feedback", {
        method: "PATCH",
        body: JSON.stringify({ id, status })
      });
      setSelectedFeedback((current) => current?.id === id ? { ...current, status: payload.data.status, statusLabel: payload.data.statusLabel, resolvedAt: payload.data.resolvedAt } : current);
      setMessage("Status atualizado.");
      await loadAnonymousFeedback();
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Não foi possível atualizar o status.");
    }
  }

  async function deleteFeedback(feedback: AnonymousFeedbackClient) {
    const confirmed = window.confirm("Excluir este feedback permanentemente? Essa ação não pode ser desfeita.");
    if (!confirmed) return;

    setMessage("");
    setDeletingFeedbackId(feedback.id);
    try {
      const payload = await apiJson<{ data: { id: string }; message: string }>("/api/anonymous-feedback", {
        method: "DELETE",
        body: JSON.stringify({ id: feedback.id })
      });
      setSelectedFeedback((current) => current?.id === feedback.id ? null : current);
      setFeedbackPayload((current) => current ? {
        ...current,
        data: current.data.filter((item) => item.id !== feedback.id),
        pagination: {
          ...current.pagination,
          total: Math.max(0, current.pagination.total - 1)
        }
      } : current);
      setMessage(payload.message);
      await loadAnonymousFeedback();
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Não foi possível excluir o feedback.");
    } finally {
      setDeletingFeedbackId(null);
    }
  }

  function openFeedbackDetails(feedback: AnonymousFeedbackClient) {
    setSelectedFeedback(feedback);
    setResponseDraft(feedback.response ?? "");
  }

  async function saveFeedbackResponse() {
    if (!selectedFeedback || responseDraft.trim().length < 3) return;
    setMessage("");
    setResponseSaving(true);
    try {
      const payload = await apiJson<{ data: AnonymousFeedbackClient }>("/api/anonymous-feedback", {
        method: "PATCH",
        body: JSON.stringify({ id: selectedFeedback.id, response: responseDraft.trim() })
      });
      setSelectedFeedback((current) => current ? {
        ...current,
        response: payload.data.response,
        respondedAt: payload.data.respondedAt,
        respondedBy: "East River"
      } : current);
      setResponseDraft(payload.data.response ?? responseDraft.trim());
      setMessage("Resposta enviada ao colaborador como East River.");
      await loadAnonymousFeedback();
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Não foi possível enviar a resposta.");
    } finally {
      setResponseSaving(false);
    }
  }

  if (feedbackView === "loading") {
    return (
      <div>
        <PageHeader title="Feedback Anônimo" description="Canal seguro para registrar percepções, sugestões e problemas operacionais." icon={MessageCircle} actions={<TopActions />} />
        <Panel title="Carregando">
          <EmptyState title="Carregando Feedback Anônimo" description="Verificando sua permissão de acesso." />
        </Panel>
      </div>
    );
  }

  if (feedbackView === "error") {
    return (
      <div>
        <PageHeader title="Feedback Anônimo" description="Canal seguro para registrar percepções, sugestões e problemas operacionais." icon={MessageCircle} actions={<TopActions />} />
        <Panel title="Não foi possível carregar">
          <div className="rounded-lg border border-red-100 bg-red-50 p-5 text-center">
            <AlertTriangle className="mx-auto h-9 w-9 text-red-500" />
            <p className="mt-3 text-sm font-extrabold text-red-800">{message || "Não foi possível carregar Feedback Anônimo."}</p>
            <button type="button" onClick={loadAnonymousFeedback} disabled={feedbackLoading} className="mt-4 h-10 rounded-lg border border-red-200 bg-white px-4 text-sm font-extrabold text-red-700 disabled:opacity-60">
              {feedbackLoading ? "Tentando novamente..." : "Tentar novamente"}
            </button>
          </div>
        </Panel>
      </div>
    );
  }

  if (feedbackView === "admin") {
    const summary = feedbackPayload?.summary;
    const exportParams = new URLSearchParams();
    if (feedbackFilters.status !== "Todos") exportParams.set("status", feedbackFilters.status);
    if (feedbackFilters.urgency !== "Todos") exportParams.set("urgency", feedbackFilters.urgency);
    if (feedbackFilters.category !== "Todos") exportParams.set("category", feedbackFilters.category);
    if (feedbackFilters.startDate) exportParams.set("startDate", feedbackFilters.startDate);
    if (feedbackFilters.endDate) exportParams.set("endDate", feedbackFilters.endDate);
    if (feedbackFilters.lob.trim()) exportParams.set("lob", feedbackFilters.lob.trim());
    if (feedbackFilters.jobTitle.trim()) exportParams.set("jobTitle", feedbackFilters.jobTitle.trim());
    if (feedbackFilters.search.trim()) exportParams.set("search", feedbackFilters.search.trim());
    return (
      <div>
        <PageHeader title="Feedback Anônimo" description="Acompanhe manifestações, responda aos colaboradores e preserve a escolha de identificação." icon={MessageCircle} actions={<TopActions />} />
        {message ? <div className="mb-4 rounded-lg border border-blue-100 bg-blue-50 px-4 py-3 text-sm font-bold text-blue-700">{message}</div> : null}
        <div className="mb-5 grid gap-4 md:grid-cols-2 xl:grid-cols-5">
          <StatCard title="Total" value={summary?.total ?? 0} helper="feedbacks recebidos" icon={MessageCircle} tone="blue" />
          <StatCard title="Novos" value={summary?.new ?? 0} helper="aguardando leitura" icon={Send} tone="cyan" />
          <StatCard title="Em análise" value={summary?.inReview ?? 0} helper="em tratamento" icon={RefreshCw} tone="orange" />
          <StatCard title="Resolvidos" value={summary?.resolved ?? 0} helper="concluídos" icon={CheckCircle2} tone="green" />
          <StatCard title="Críticos" value={summary?.critical ?? 0} helper="urgência crítica" icon={AlertTriangle} tone="red" />
        </div>
        <Panel title="Feedbacks recebidos" action="Exportar" actionOnClick={() => void downloadFile(`/api/anonymous-feedback/export?${exportParams.toString()}`, "feedback_anonimo.xlsx").catch((error) => setMessage(error.message))}>
          <div className="mb-4 grid gap-3 md:grid-cols-4 xl:grid-cols-8">
            <select value={feedbackFilters.status} onChange={(event) => setFeedbackFilters({ ...feedbackFilters, status: event.target.value })} className="h-10 rounded-lg border border-border px-3">
              {feedbackStatusOptions.map((option) => <option key={option}>{option}</option>)}
            </select>
            <select value={feedbackFilters.urgency} onChange={(event) => setFeedbackFilters({ ...feedbackFilters, urgency: event.target.value })} className="h-10 rounded-lg border border-border px-3">
              <option>Todos</option>
              {urgencyOptions.map((option) => <option key={option}>{option}</option>)}
            </select>
            <select value={feedbackFilters.category} onChange={(event) => setFeedbackFilters({ ...feedbackFilters, category: event.target.value })} className="h-10 rounded-lg border border-border px-3">
              <option>Todos</option>
              {anonymousCategories.map((option) => <option key={option}>{option}</option>)}
            </select>
            <input type="date" value={feedbackFilters.startDate} onChange={(event) => setFeedbackFilters({ ...feedbackFilters, startDate: event.target.value })} className="h-10 rounded-lg border border-border px-3" />
            <input type="date" value={feedbackFilters.endDate} onChange={(event) => setFeedbackFilters({ ...feedbackFilters, endDate: event.target.value })} className="h-10 rounded-lg border border-border px-3" />
            <input value={feedbackFilters.lob} onChange={(event) => setFeedbackFilters({ ...feedbackFilters, lob: event.target.value })} className="h-10 rounded-lg border border-border px-3" placeholder="LOB" />
            <input value={feedbackFilters.jobTitle} onChange={(event) => setFeedbackFilters({ ...feedbackFilters, jobTitle: event.target.value })} className="h-10 rounded-lg border border-border px-3" placeholder="Cargo/Função" />
            <div className="flex gap-2 xl:col-span-1">
              <input value={feedbackFilters.search} onChange={(event) => setFeedbackFilters({ ...feedbackFilters, search: event.target.value })} className="h-10 min-w-0 flex-1 rounded-lg border border-border px-3" placeholder="Buscar comentário" />
              <button type="button" onClick={loadAnonymousFeedback} className="h-10 rounded-lg border border-border px-3 text-sm font-bold">Buscar</button>
            </div>
          </div>
          {feedbackLoading ? (
            <EmptyState title="Carregando feedbacks" description="Buscando dados reais no banco." />
          ) : feedbackPayload?.data.length ? (
            <SimpleTable
              columns={["Data", "Categoria", "Urgência", "LOB", "Cargo/Função", "Comentário", "Status", "Identificação", "Retorno", "Ações"]}
              rows={feedbackPayload.data.map((feedback) => [
                ptDate(feedback.createdAt),
                feedback.category,
                <PriorityBadge key={`${feedback.id}-urgency`} priority={feedback.urgencyLabel} />,
                feedback.lob ?? "-",
                feedback.jobTitle ?? "-",
                <div key={`${feedback.id}-comment`} className="max-w-[420px]">
                  <p className="line-clamp-3 text-sm">{feedback.comment}</p>
                </div>,
                <StatusBadge key={`${feedback.id}-status`} status={feedback.statusLabel} />,
                feedback.allowContact ? <StatusBadge key={`${feedback.id}-contact`} status="Identificado" /> : <StatusBadge key={`${feedback.id}-anonymous`} status="Anônimo" />,
                feedback.response ? <StatusBadge key={`${feedback.id}-response`} status="Respondido" /> : <StatusBadge key={`${feedback.id}-pending-response`} status="Aguardando" />,
                <div key={`${feedback.id}-actions`} className="flex flex-wrap gap-2">
                  <button type="button" onClick={() => openFeedbackDetails(feedback)} className="rounded-lg border border-blue-200 bg-blue-50 px-2 py-1 text-xs font-bold text-blue-700">{feedback.response ? "Ver resposta" : "Responder"}</button>
                  <button type="button" onClick={() => updateFeedbackStatus(feedback.id, "Em análise")} className="rounded-lg border border-blue-200 bg-blue-50 px-2 py-1 text-xs font-bold text-blue-700">Em análise</button>
                  <button type="button" onClick={() => updateFeedbackStatus(feedback.id, "Resolvido")} className="rounded-lg border border-emerald-200 bg-emerald-50 px-2 py-1 text-xs font-bold text-emerald-700">Resolver</button>
                  <button type="button" onClick={() => void deleteFeedback(feedback)} disabled={deletingFeedbackId === feedback.id} className="inline-flex items-center gap-1 rounded-lg border border-red-200 bg-red-50 px-2 py-1 text-xs font-bold text-red-700 disabled:cursor-not-allowed disabled:opacity-60">
                    <Trash2 className="h-3.5 w-3.5" />
                    {deletingFeedbackId === feedback.id ? "Excluindo..." : "Excluir"}
                  </button>
                </div>
              ])}
            />
          ) : (
            <EmptyState title="Nenhum feedback recebido ainda." description="Os feedbacks enviados pelos colaboradores aparecerão aqui." />
          )}
        </Panel>
        {selectedFeedback ? (
          <div className="fixed inset-0 z-50 grid place-items-center bg-navy-950/40 p-4 backdrop-blur-sm">
            <div className="card max-h-[88vh] w-full max-w-2xl overflow-y-auto p-5">
              <div className="mb-4 flex items-start justify-between gap-3">
                <div>
                  <h2 className="text-lg font-extrabold text-navy-950">Detalhe do feedback</h2>
                  <p className="text-sm text-muted">{ptDate(selectedFeedback.createdAt)} · {selectedFeedback.category}</p>
                </div>
                <button type="button" onClick={() => setSelectedFeedback(null)} aria-label="Fechar detalhe do feedback" className="grid h-9 w-9 place-items-center rounded-lg hover:bg-slate-100">×</button>
              </div>
              <div className="space-y-3">
                <div className="flex flex-wrap gap-2">
                  <PriorityBadge priority={selectedFeedback.urgencyLabel} />
                  <StatusBadge status={selectedFeedback.statusLabel} />
                  {selectedFeedback.allowContact ? <StatusBadge status="Identificado" /> : <span className="inline-flex rounded-md bg-slate-100 px-2 py-1 text-xs font-extrabold text-slate-600">Anônimo</span>}
                </div>
                <div className="grid gap-3 md:grid-cols-2">
                  <div className="rounded-lg border border-border p-3">
                    <p className="text-xs font-extrabold uppercase tracking-wide text-muted">LOB</p>
                    <p className="mt-1 font-bold text-navy-950">{selectedFeedback.lob ?? "-"}</p>
                  </div>
                  <div className="rounded-lg border border-border p-3">
                    <p className="text-xs font-extrabold uppercase tracking-wide text-muted">Cargo/Função</p>
                    <p className="mt-1 font-bold text-navy-950">{selectedFeedback.jobTitle ?? "-"}</p>
                  </div>
                </div>
                <div className="rounded-lg border border-border p-3">
                  <p className="text-xs font-extrabold uppercase tracking-wide text-muted">Comentário</p>
                  <p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-navy-950">{selectedFeedback.comment}</p>
                </div>
                {selectedFeedback.allowContact && selectedFeedback.contact ? (
                  <div className="rounded-lg border border-blue-100 bg-blue-50 p-3 text-sm text-blue-800">
                    <p className="font-extrabold">Contato permitido pelo colaborador</p>
                    <p className="mt-1">{selectedFeedback.contact.name} · {selectedFeedback.contact.email} · {selectedFeedback.contact.wbLogin}</p>
                  </div>
                ) : (
                  <div className="rounded-lg border border-slate-200 bg-slate-50 p-3 text-sm text-slate-700">
                    <p className="font-extrabold">Identidade protegida</p>
                    <p className="mt-1">O colaborador optou por permanecer anônimo. Nenhum dado de identificação é exibido nesta área.</p>
                  </div>
                )}
                <div className="rounded-lg border border-emerald-100 bg-emerald-50/60 p-3">
                  <div className="flex flex-wrap items-center justify-between gap-2">
                    <div>
                      <p className="text-sm font-extrabold text-navy-950">Resposta para o colaborador</p>
                      <p className="mt-1 text-xs font-semibold text-emerald-800">No perfil do colaborador, o remetente será exibido somente como East River.</p>
                    </div>
                    {selectedFeedback.respondedAt ? <p className="text-xs font-bold text-emerald-700">Último envio: {ptDate(selectedFeedback.respondedAt)}</p> : null}
                  </div>
                  <label className="mt-3 block">
                    <span className="sr-only">Resposta da East River para o colaborador</span>
                    <textarea
                      value={responseDraft}
                      onChange={(event) => setResponseDraft(event.target.value)}
                      maxLength={4000}
                      className="min-h-32 w-full rounded-lg border border-emerald-200 bg-white p-3 text-sm leading-6 outline-none focus:border-emerald-400"
                      placeholder="Escreva o posicionamento ou retorno da East River"
                    />
                  </label>
                  <div className="mt-2 flex flex-wrap items-center justify-between gap-2">
                    <p className="text-xs font-semibold text-muted">{responseDraft.length}/4000 caracteres</p>
                    <button type="button" onClick={saveFeedbackResponse} disabled={responseSaving || responseDraft.trim().length < 3} className="premium-button h-10 px-4 text-sm font-extrabold disabled:opacity-60">
                      {responseSaving ? "Enviando..." : selectedFeedback.response ? "Atualizar resposta" : "Enviar resposta"}
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        ) : null}
      </div>
    );
  }

  return (
    <div>
      <PageHeader title="Feedback Anônimo" description="Canal seguro para registrar percepções, acompanhar o tratamento e receber o retorno da East River." icon={MessageCircle} actions={<TopActions />} />
      {message ? <div className="mb-4 rounded-lg border border-blue-100 bg-blue-50 px-4 py-3 text-sm font-bold text-blue-700">{message}</div> : null}
      <Panel title="Enviar feedback anônimo">
        {submitted ? (
          <div className="rounded-lg border border-emerald-100 bg-emerald-50 p-5 text-center">
            <CheckCircle2 className="mx-auto h-10 w-10 text-emerald-600" />
            <h2 className="mt-3 text-lg font-extrabold text-navy-950">Feedback enviado com sucesso.</h2>
            <p className="mt-1 text-sm font-semibold text-muted">Você poderá acompanhar o status e a resposta da East River em Meu Perfil.</p>
            <Link href="/meu-perfil#meus-feedbacks" className="mt-4 inline-flex h-10 items-center rounded-lg bg-emerald-600 px-4 text-sm font-extrabold text-white hover:bg-emerald-700">Acompanhar em Meu Perfil</Link>
          </div>
        ) : (
          <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_320px]">
            <div className="space-y-4">
              <label className="block">
                <span className="mb-1.5 block text-sm font-bold text-muted">Categoria</span>
                <select value={anonymousForm.category} onChange={(event) => setAnonymousForm({ ...anonymousForm, category: event.target.value })} className="h-11 w-full rounded-lg border border-border px-3">
                  {anonymousCategories.map((category) => <option key={category}>{category}</option>)}
                </select>
              </label>
              <label className="block">
                <span className="mb-1.5 block text-sm font-bold text-muted">Nível de urgência</span>
                <select value={anonymousForm.urgency} onChange={(event) => setAnonymousForm({ ...anonymousForm, urgency: event.target.value })} className="h-11 w-full rounded-lg border border-border px-3">
                  {urgencyOptions.map((urgency) => <option key={urgency}>{urgency}</option>)}
                </select>
              </label>
              <label className="block">
                <span className="mb-1.5 block text-sm font-bold text-muted">Comentário</span>
                <textarea value={anonymousForm.comment} onChange={(event) => setAnonymousForm({ ...anonymousForm, comment: event.target.value })} className="min-h-40 w-full rounded-lg border border-border p-3 outline-none" placeholder="Descreva a situação, oportunidade ou sugestão" />
              </label>
              <label className="flex items-start gap-3 rounded-lg border border-border bg-slate-50 p-3 text-sm font-bold text-navy-950">
                <input type="checkbox" checked={anonymousForm.allowContact} onChange={(event) => setAnonymousForm({ ...anonymousForm, allowContact: event.target.checked })} className="mt-0.5 h-4 w-4" />
                <span>
                  Quero me identificar para a equipe responsável
                  <span className="mt-1 block text-xs font-semibold leading-5 text-muted">Ao marcar, seu nome, e-mail e WB/Login poderão ser vistos pelos perfis autorizados. Desmarcado, o envio permanece anônimo.</span>
                </span>
              </label>
              <button type="button" onClick={submitAnonymousFeedback} disabled={!anonymousForm.comment.trim()} className="premium-button h-11 px-5 text-sm font-extrabold disabled:opacity-60">Enviar feedback</button>
            </div>
            <div className="rounded-lg border border-blue-100 bg-blue-50 p-4 text-sm font-semibold leading-6 text-blue-800">
              Sua escolha de privacidade é respeitada. Sem identificação, administradores não recebem seu nome, e-mail ou WB/Login. O sistema mantém apenas um vínculo privado para mostrar o protocolo e a resposta exclusivamente no seu próprio perfil.
            </div>
          </div>
        )}
      </Panel>
    </div>
  );
}

export function TokensPage() {
  const [balance, setBalance] = useState(430);
  const [redemptions, setRedemptions] = useState(tokenHistory);
  const [rewardCatalog, setRewardCatalog] = useState<RewardItem[]>(rewards.map((reward, index) => ({ id: `RWD-${index + 1}`, name: reward.name, cost: reward.cost, stock: reward.stock })));
  const [tokenMessage, setTokenMessage] = useState("");

  useEffect(() => {
    apiJson<{ data: { balance: number; history: typeof tokenHistory; rewards: RewardItem[] } }>("/api/tokens")
      .then((payload) => {
        setBalance(payload.data.balance);
        setRedemptions(payload.data.history);
        setRewardCatalog(payload.data.rewards);
      })
      .catch(() => undefined);
  }, []);

  async function redeem(reward: RewardItem) {
    const payload = await apiJson<{ data: { requestId: string; newBalance: number; transaction: (typeof tokenHistory)[number] } }>("/api/tokens/redeem", {
      method: "POST",
      body: JSON.stringify({ rewardId: reward.id, cost: reward.cost })
    });
    setBalance(payload.data.newBalance);
    setRedemptions((items) => [payload.data.transaction, ...items]);
    setTokenMessage(`Resgate solicitado. Solicitação ${payload.data.requestId} criada para aprovação.`);
  }

  return (
    <div>
      <PageHeader title="Tokens e Recompensas" description="Acompanhe saldo, ganhos, resgates e reconhecimento operacional." icon={Coins} actions={<TopActions />} />
      <div className="grid gap-5 xl:grid-cols-[380px_minmax(0,1fr)]">
        <div className="space-y-5">
          <Panel title="Saldo de Tokens">
            <div className="rounded-xl bg-navy-950 p-6 text-white">
              <Coins className="h-10 w-10 text-amber-300" />
              <p className="mt-4 text-sm text-blue-100">Saldo disponível</p>
              <p className="text-5xl font-extrabold">{balance}</p>
              <p className="mt-2 text-sm text-blue-100">Tokens podem ser usados em recompensas aprovadas.</p>
            </div>
          </Panel>
          <Panel title="Regras de pontuação">
            <MiniAlertList
              items={[
                { title: "Presença gera tokens", status: "+5/dia", tone: "green" },
                { title: "Qualidade acima da meta", status: "+80", tone: "green" },
                { title: "Produtividade acima da meta", status: "+60", tone: "blue" },
                { title: "Reconhecimento manual", status: "Variável", tone: "orange" }
              ]}
            />
          </Panel>
        </div>
        <div className="space-y-5">
          <Panel title="Catálogo de Recompensas">
            {tokenMessage ? (
              <div className="mb-4 rounded-lg border border-amber-200 bg-amber-50 px-4 py-3 text-sm font-bold text-amber-700">{tokenMessage}</div>
            ) : null}
            <div className="grid gap-4 md:grid-cols-4">
              {rewardCatalog.map((reward) => {
                const Icon = getRewardIcon(reward.name);
                return (
                  <div key={reward.name} className="rounded-lg border border-border p-4">
                    <Icon className="h-9 w-9 text-blue-600" />
                    <p className="mt-3 font-extrabold text-navy-950">{reward.name}</p>
                    <p className="text-sm text-muted">Estoque: {reward.stock}</p>
                    <p className="mt-3 text-lg font-extrabold text-amber-500">{reward.cost} tokens</p>
                    <button onClick={() => redeem(reward)} className="mt-3 w-full rounded-lg bg-blue-600 px-3 py-2 text-sm font-bold text-white">Solicitar resgate</button>
                  </div>
                );
              })}
            </div>
          </Panel>
          <div className="grid gap-5 xl:grid-cols-2">
            <Panel title="Histórico de Tokens">
              <SimpleTable columns={["Evento", "Tokens", "Data", "Tipo"]} rows={redemptions.map((item) => [item.title, item.amount, item.date, <StatusBadge key={item.title} status={item.type} />])} />
            </Panel>
            <Panel title="Ranking de Engajamento">
              <SimpleTable columns={["Pos.", "Pessoa", "Tokens"]} rows={topPerformers.map((person, index) => [`${index + 1}º`, person.name, 760 - index * 58])} />
            </Panel>
          </div>
        </div>
      </div>
    </div>
  );
}

export function ChatPage() {
  const { data: session } = useSession();
  const [messages, setMessages] = useState(chatMessages.map((message, index) => ({ id: `MSG-${index + 1}`, ...message })));
  const [text, setText] = useState("");

  useEffect(() => {
    apiJson<{ data: Array<{ id: string; author: string; message: string; time: string; self: boolean }> }>("/api/chat/messages?roomId=equipe-alfa")
      .then((payload) => setMessages(payload.data))
      .catch(() => undefined);
  }, []);

  async function sendMessage() {
    if (!text.trim()) return;
    const payload = await apiJson<{ data: { id: string; author: string; message: string; time: string; self: boolean } }>("/api/chat/messages", {
      method: "POST",
      body: JSON.stringify({ roomId: "equipe-alfa", content: text })
    });
    setMessages([...messages, { ...payload.data, author: session?.user?.name ?? payload.data.author }]);
    setText("");
  }

  return (
    <div>
      <PageHeader title="Chat" description="Conversas individuais, grupos por time, LOB e área." icon={MessageCircle} actions={<TopActions />} />
      <div className="grid gap-5 xl:grid-cols-[360px_minmax(0,1fr)]">
        <Panel title="Conversas">
          {["Equipe Alfa", "CEC - Operação", "WFM e Supervisores", "Qualidade", "TI Suporte"].map((room, index) => (
            <button key={room} className={cn("mb-2 flex w-full items-center gap-3 rounded-lg p-3 text-left last:mb-0", index === 0 ? "bg-blue-50" : "hover:bg-slate-50")}>
              <span className="grid h-10 w-10 place-items-center rounded-full bg-blue-600 text-sm font-bold text-white">{initials(room)}</span>
              <span>
                <p className="font-bold text-navy-950">{room}</p>
                <p className="text-xs text-muted">{index % 2 === 0 ? "Online" : "Grupo"}</p>
              </span>
            </button>
          ))}
        </Panel>
        <section className="card flex min-h-[640px] flex-col overflow-hidden">
          <div className="flex items-center justify-between border-b border-border px-5 py-4">
            <div>
              <h2 className="text-lg font-extrabold text-navy-950">Equipe Alfa</h2>
              <p className="text-sm text-muted">12 participantes online</p>
            </div>
            <StatusBadge status="Online" />
          </div>
          <div className="flex-1 space-y-4 overflow-y-auto bg-slate-50/55 p-5">
            {messages.map((message) => (
              <div key={message.id} className={cn("flex", message.self ? "justify-end" : "justify-start")}>
                <div className={cn("max-w-[72%] rounded-xl p-4 shadow-soft", message.self ? "bg-blue-600 text-white" : "bg-white text-navy-950")}>
                  <p className="text-xs font-bold opacity-75">{message.author} • {message.time}</p>
                  <p className="mt-1 text-sm">{message.message}</p>
                </div>
              </div>
            ))}
          </div>
          <div className="flex gap-3 border-t border-border p-4">
            <input value={text} onChange={(event) => setText(event.target.value)} onKeyDown={(event) => event.key === "Enter" && sendMessage()} className="h-12 flex-1 rounded-lg border border-border px-4 outline-none" placeholder="Digite sua mensagem..." />
            <button onClick={sendMessage} className="grid h-12 w-12 place-items-center rounded-lg bg-blue-600 text-white">
              <Send className="h-5 w-5" />
            </button>
          </div>
        </section>
      </div>
    </div>
  );
}

